export const PatchAdminUserResponse = zod.object({
  "id": zod.string(),
  "email": zod.string().email().nullable(),
  "fullName": zod.string().nullable(),
  "role": zod.enum(['admin', 'member']),
  "appAccess": zod.enum(['active', 'not_invited']).describe('Whether the account is authorized to use this application.'),
  "banned": zod.boolean(),
  "createdAt": zod.coerce.date(),
  "lastSignInAt": zod.coerce.date().nullable()
})


/**
 * Administrators cannot delete themselves, the bootstrap administrator, or another administrator account.
 * @summary Permanently delete a member account and its dashboard data
 */
export const deleteAdminUserPathUserIdMax = 64;



export const DeleteAdminUserParams = zod.object({
  "userId": zod.coerce.string().min(1).max(deleteAdminUserPathUserIdMax)
})

export const DeleteAdminUserResponse = zod.void()


